 private boolean folderHidden(String folder,String title,String album){String f=folder.toLowerCase(Locale.ROOT),t=title.toLowerCase(Locale.ROOT),a=album.toLowerCase(Locale.ROOT);boolean chat=f.contains("whatsapp")||f.contains("voice notes")||f.contains("telegram audio");boolean recording=f.contains("recordings")||f.contains("recorder")||f.contains("grabaciones");return excluded.contains(folder)||(getPreferences(0).getBoolean("hideChat",true)&&(chat||a.contains("whatsapp audio")||t.matches("(aud|ptt)-.*-wa[0-9]+.*")))||(getPreferences(0).getBoolean("hideRecordings",true)&&recording);}
 private void scan(){boolean wasSettings=settingsScreen;new Thread(()->{ArrayList<Song> loaded=new ArrayList<>();TreeMap<String,Integer> found=new TreeMap<>();int hidden=0;try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,new String[]{"_id","title","artist","album","album_id","duration",Build.VERSION.SDK_INT>=29?"relative_path":"_data"},"duration > 0",null,"title COLLATE NOCASE ASC")){if(c!=null)while(c.moveToNext()){String title=c.getString(1)==null?"Sin título":c.getString(1),album=c.getString(3)==null?"Sin álbum":c.getString(3);String folder=c.getString(6);if(folder==null)folder="Sin carpeta";if(Build.VERSION.SDK_INT<29){int last=folder.lastIndexOf('/');folder=last>=0?folder.substring(0,last+1):folder;}found.put(folder,found.getOrDefault(folder,0)+1);if(folderHidden(folder,title,album)){hidden++;continue;}loaded.add(new Song(c.getLong(0),c.getLong(4),c.getLong(5),title,c.getString(2)==null?"Artista desconocido":c.getString(2),album,ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,c.getLong(0))));}}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"No se pudo leer la biblioteca",Toast.LENGTH_LONG).show());}final int h=hidden;runOnUiThread(()->{songs.clear();songs.addAll(loaded);folders.clear();folders.putAll(found);hiddenCount=h;if(wasSettings)showSettings();else render();});}).start();}
