 private void chooseFolders(){String[] names=folders.keySet().toArray(new String[0]);if(names.length==0){Toast.makeText(this,"No hay carpetas de audio",Toast.LENGTH_SHORT).show();return;}boolean[] checked=new boolean[names.length];for(int i=0;i<names.length;i++)checked[i]=excluded.contains(names[i]);String[] labels=new String[names.length];for(int i=0;i<names.length;i++)labels[i]=names[i]+" ("+folders.get(names[i])+")";new AlertDialog.Builder(this).setTitle("Ocultar estas carpetas").setMultiChoiceItems(labels,checked,(dlg,n,on)->checked[n]=on).setPositiveButton("Guardar",(dlg,n)->{excluded.clear();for(int i=0;i<names.length;i++)if(checked[i])excluded.add(names[i]);getPreferences(0).edit().putString("excluded",new JSONArray(excluded).toString()).apply();scan();}).setNegativeButton("Cancelar",null).show();}
