 private void buildLists(){content.addView(button("+  Crear lista",()->createList(null)));ScrollView s=new ScrollView(this);LinearLayout box=column();s.addView(box);content.addView(s,new LinearLayout.LayoutParams(-1,0,1));if(lists.length()==0){TextView empty=text("La próxima canción merece una lista.",23,INK,true);empty.setPadding(0,d(32),0,d(12));box.addView(empty);box.addView(text("Crea una lista y añade canciones desde el botón + con el botón +.",15,MUTED,false));}Iterator<String> keys=lists.keys();while(keys.hasNext()){String name=keys.next();JSONArray ids=lists.optJSONArray(name);LinearLayout line=row();line.setPadding(0,d(16),0,d(16));TextView art=text("≡",24,LIME,true);art.setGravity(Gravity.CENTER);art.setBackground(shape(CARD,16));line.addView(art,new LinearLayout.LayoutParams(d(58),d(58)));LinearLayout meta=column();meta.setPadding(d(14),0,0,0);meta.addView(text(name,18,INK,true));meta.addView(text((ids==null?0:ids.length())+" canciones",12,MUTED,false));line.addView(meta,new LinearLayout.LayoutParams(0,-2,1));line.addView(button("⋮",()->new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"Cambiar nombre","Eliminar lista"},(dlg,n)->{if(n==0)renameList(name);else new AlertDialog.Builder(this).setTitle("¿Eliminar la lista?").setMessage("Los archivos de música no se borran.").setPositiveButton("Eliminar",(x,y)->{lists.remove(name);save();render();}).setNegativeButton("Cancelar",null).show();}).show()));line.setOnClickListener(v->{activeList=name;render();});box.addView(line);}}
 private void createList(Song song){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Nombre de la lista");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Nueva lista").setView(input).setPositiveButton("Crear",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(dlg->dialog.getButton(-1).setOnClickListener(v->{String name=input.getText().toString().trim();if(name.isEmpty()||lists.has(name)){input.setError(name.isEmpty()?"Pon un nombre":"Ya existe esa lista");return;}try{JSONArray a=new JSONArray();if(song!=null)a.put(song.id);lists.put(name,a);save();dialog.dismiss();if(tab.equals("Listas"))render();Toast.makeText(this,"Lista creada",Toast.LENGTH_SHORT).show();}catch(Exception ignored){}}));dialog.show();}
