 private void addToList(Song song){ArrayList<String> names=new ArrayList<>();names.add("+ Crear lista");Iterator<String> i=lists.keys();while(i.hasNext())names.add(i.next());new AlertDialog.Builder(this).setTitle("Añadir a lista").setItems(names.toArray(new String[0]),(dlg,n)->{if(n==0){createList(song);return;}String name=names.get(n);JSONArray a=lists.optJSONArray(name);if(has(a,song.id)){Toast.makeText(this,"Ya está en "+name,Toast.LENGTH_SHORT).show();return;}a.put(song.id);save();Toast.makeText(this,"Añadida a "+name,Toast.LENGTH_SHORT).show();}).show();}
