 private void fillSongs(){if(rows==null)return;rows.removeAllViews();visible.clear();String q=query.toLowerCase(Locale.ROOT);for(Song s:songs)if((!tab.equals("Favoritos")||favorite(s))&&(activeList==null||has(lists.optJSONArray(activeList),s.id))&&(s.title+" "+s.artist+" "+s.album).toLowerCase(Locale.ROOT).contains(q))visible.add(s);if(getSharedPreferences("music",0).getString("sort","name").equals("plays"))visible.sort(Comparator.comparingInt((Song x)->plays(x)).reversed().thenComparing(x->x.title.toLowerCase(Locale.ROOT)));if(tab.equals("Álbumes"))visible.sort(Comparator.comparing(s->s.album));if(visible.isEmpty()){TextView t=text(tab.equals("Favoritos")?"Tus favoritas, a un toque":activeList!=null?"Esta lista espera sus canciones":songs.isEmpty()?"Todavía no hay música aquí":"No hay coincidencias",21,INK,true);t.setPadding(0,d(30),0,d(14));rows.addView(t);rows.addView(text(songs.isEmpty()?"Copia tus archivos de audio a Música o Descargas y pulsa ↻. No necesitas conexión.":activeList!=null?"Añade canciones desde Canciones con el botón +.":"Prueba otro título, artista o álbum.",15,MUTED,false));return;}String album="";for(int j=0;j<visible.size();j++){final int pos=j;Song s=visible.get(j);if(tab.equals("Álbumes")&&!album.equals(s.album)){album=s.album;TextView h=text(album,18,LIME,true);h.setPadding(0,d(18),0,d(8));rows.addView(h);}LinearLayout line=row();line.setPadding(0,d(8),0,d(8));TextView art=text("♫",25,LIME,false);art.setGravity(Gravity.CENTER);art.setBackground(shape(CARD,14));line.addView(art,new LinearLayout.LayoutParams(d(54),d(54)));LinearLayout meta=column();meta.setPadding(d(12),0,d(8),0);TextView title=text(s.title,15,INK,true);title.setMaxLines(2);meta.addView(title);TextView sub=text(s.subtitle()+" · "+Song.time(s.duration)+(getSharedPreferences("music",0).getString("sort","name").equals("plays")?" · "+plays(s)+" rep.":""),12,MUTED,false);sub.setMaxLines(1);sub.setEllipsize(TextUtils.TruncateAt.END);sub.setPadding(0,d(5),0,0);meta.addView(sub);line.addView(meta,new LinearLayout.LayoutParams(0,-2,1));TextView heart=button(favorite(s)?"♥":"♡",()->toggleFavorite(s));heart.setTextColor(favorite(s)?LIME:MUTED);heart.setPadding(0,0,0,0);line.addView(heart,new LinearLayout.LayoutParams(d(42),d(48)));TextView plus=button(activeList==null?"+":"−",()->{if(activeList==null)addToList(s);else removeFromList(s);});plus.setPadding(d(10),0,d(10),0);line.addView(plus,new LinearLayout.LayoutParams(d(44),d(48)));line.setOnClickListener(v->{if(service!=null){startService(new Intent(this,PlayerService.class));service.play(new ArrayList<>(visible),pos);showPlayer();}});rows.addView(line);}}
