 private float sx,sy;private boolean swiping=false;@Override public boolean dispatchTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){sx=e.getX();sy=e.getY();swiping=false;}if(e.getAction()==MotionEvent.ACTION_MOVE&&!playerScreen&&!settingsScreen&&Math.abs(e.getX()-sx)>d(65)&&Math.abs(e.getY()-sy)<d(45)){if(!swiping){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();}swiping=true;return true;}if(e.getAction()==MotionEvent.ACTION_UP&&swiping){String[] tabs={"Listas","Canciones","Álbumes","Favoritos"};int current=tab.equals("Listas")?0:tab.equals("Canciones")?1:tab.equals("Álbumes")?2:3;int next=current+(e.getX()>sx?-1:1);if(next>=0&&next<4){tab=tabs[next];activeList=null;query="";render();}swiping=false;return true;}return super.dispatchTouchEvent(e);}
